def test_gather1(self):
    def fn(a, b):
        return (
            torch.gather(a.expand([4, 5, 10, 6]), 3, b + 1),
            torch.gather(a.expand([4, 5, 10, 6]), -1, b + 1),
        )

    self.common(
        fn,
        (
            torch.randn([1, 1, 10, 6]),
            torch.randint(5, [4, 5, 10, 1], dtype=torch.int64),
        ),
    )

def test_gather3(self):
